css:
.avanta-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.avanta-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(26,58,92,0.3);
    text-align: center;
}

.avanta-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
}

.avanta-sim-header p {
    margin: 0;
    opacity: 0.85;
    font-size: 1rem;
}

.avanta-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 20px;
    font-weight: 600;
}

.avanta-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 25px;
}

.avanta-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.3s ease;
    border-top: 4px solid #2c5f8a;
}

.avanta-sim-status-card:hover {
    transform: translateY(-4px);
}

.avanta-sim-card-budget { border-top-color: #27ae60; }
.avanta-sim-card-revenue { border-top-color: #2c5f8a; }
.avanta-sim-card-ecom { border-top-color: #8e44ad; }
.avanta-sim-card-ebitda { border-top-color: #e67e22; }
.avanta-sim-card-nps { border-top-color: #e74c3c; }
.avanta-sim-card-cpo { border-top-color: #16a085; }

.avanta-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.avanta-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #2c3e50;
}

.avanta-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #2c5f8a;
}

.avanta-sim-briefing-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}

.avanta-sim-briefing-icon {
    font-size: 1.5rem;
}

.avanta-sim-briefing h3 {
    margin: 0;
    color: #1a3a5c;
    font-size: 1.15rem;
}

.avanta-sim-briefing p {
    margin: 0;
    color: #555;
    line-height: 1.6;
}

.avanta-sim-event {
    background: #fff3cd;
    border: 1px solid #ffc107;
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 20px;
}

.avanta-sim-event h4 {
    color: #856404;
    margin: 0 0 10px 0;
}

.avanta-sim-event p {
    margin: 0;
    color: #664d03;
}

.avanta-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.avanta-sim-controls h3 {
    margin: 0 0 20px 0;
    color: #1a3a5c;
}

.avanta-sim-decision-group {
    margin-bottom: 18px;
}

.avanta-sim-decision-group label {
    display: block;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 5px;
}

.avanta-sim-decision-group select {
    border-radius: 8px;
    border: 2px solid #dde4ec;
    padding: 10px 12px;
    font-size: 0.95rem;
    width: 100%;
    transition: border-color 0.3s;
}

.avanta-sim-decision-group select:focus {
    border-color: #2c5f8a;
    outline: none;
    box-shadow: 0 0 0 3px rgba(44,95,138,0.15);
}

.avanta-sim-cost-hint {
    display: block;
    margin-top: 4px;
    color: #888;
    font-size: 0.82rem;
}

.avanta-sim-btn-row {
    display: flex;
    gap: 12px;
    margin-top: 20px;
    align-items: center;
}

.avanta-sim-btn-row .btn-primary {
    background: linear-gradient(135deg, #1a3a5c, #2c5f8a);
    border: none;
    border-radius: 10px;
    padding: 12px 30px;
    font-weight: 600;
}

.avanta-sim-btn-row .btn-primary:hover {
    background: linear-gradient(135deg, #15304d, #24507a);
}

.avanta-sim-history {
    margin-bottom: 25px;
}

.avanta-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 30px;
}

.avanta-sim-chart-box {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    position: relative;
    height: 300px;
}

@media (max-width: 768px) {
    .avanta-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .avanta-sim-charts {
        grid-template-columns: 1fr;
    }
    .avanta-sim-header h1 {
        font-size: 1.4rem;
    }
}

/* ===== v1.1.0 completion debrief (append-only) ===== */
.omni-cm { font-family: inherit; color: #1a202c; padding: 8px 4px; }
.omni-cm-scoreblock { text-align: center; margin-bottom: 18px; }
.omni-cm-scorenum { font-size: 3rem; font-weight: 800; line-height: 1; color: #6b46c1; }
.omni-cm-scoremax { font-size: 1.2rem; font-weight: 600; color: #a0aec0; }
.omni-cm-scorelabel { font-size: .82rem; text-transform: uppercase; letter-spacing: .05em; color: #718096; margin-top: 4px; }
.omni-cm-grade { font-size: 1.3rem; font-weight: 700; margin-top: 8px; color: #553c9a; }
.omni-cm-badge { display: inline-block; margin-top: 10px; padding: 5px 14px; border-radius: 999px; font-size: .85rem; font-weight: 700; }
.omni-cm-badge-pass { background: #c6f6d5; color: #22543d; }
.omni-cm-badge-miss { background: #fed7d7; color: #742a2a; }
.omni-cm-kpis { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; margin: 18px 0; }
.omni-cm-kpi { flex: 1 1 110px; max-width: 180px; background: #faf5ff; border: 1px solid #e9d8fd; border-radius: 10px; padding: 12px; text-align: center; }
.omni-cm-kpi-val { font-size: 1.4rem; font-weight: 800; color: #553c9a; }
.omni-cm-kpi-label { font-size: .75rem; color: #718096; margin-top: 4px; }
.omni-cm-insights { margin-top: 16px; background: #f8f4ff; border-left: 4px solid #6b46c1; border-radius: 6px; padding: 12px 16px; }
.omni-cm-insights h6 { margin: 0 0 8px; font-weight: 700; color: #553c9a; }
.omni-cm-insights ul { margin: 0; padding-left: 18px; }
.omni-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
.omni-cm-footer { margin-top: 16px; text-align: center; font-size: .85rem; color: #a0aec0; }

