                            { value: 3, labelKey: 'r2_a_opt3', cost: 900000 }
                        ]
                    },
                    decisionB: {
                        labelKey: 'r2_b_label',
                        options: [
                            { value: 0, labelKey: 'r2_b_opt0', cost: 0 },
                            { value: 1, labelKey: 'r2_b_opt1', cost: 400000 },
                            { value: 2, labelKey: 'r2_b_opt2', cost: 600000 },
                            { value: 3, labelKey: 'r2_b_opt3', cost: 1800000 }
                        ]
                    },
                    decisionC: {
                        labelKey: 'r2_c_label',
                        options: [
                            { value: 0, labelKey: 'r2_c_opt0', cost: 300000 },
                            { value: 1, labelKey: 'r2_c_opt1', cost: 800000 },
                            { value: 2, labelKey: 'r2_c_opt2', cost: 500000 },
                            { value: 3, labelKey: 'r2_c_opt3', cost: 2000000 }
                        ]
                    }
                },
                {
                    icon: '\u{1F4B0}',
                    titleKey: 'r3_title',
                    descKey: 'r3_desc',
                    decisionA: {
                        labelKey: 'r3_a_label',
                        options: [
                            { value: 0, labelKey: 'r3_a_opt0', cost: 0 },
                            { value: 1, labelKey: 'r3_a_opt1', cost: 400000 },
                            { value: 2, labelKey: 'r3_a_opt2', cost: 1800000 }
                        ]
                    },
                    decisionB: {
                        labelKey: 'r3_b_label',
                        options: [
                            { value: 0, labelKey: 'r3_b_opt0', cost: 0 },
                            { value: 1, labelKey: 'r3_b_opt1', cost: 600000 },
                            { value: 2, labelKey: 'r3_b_opt2', cost: 1200000 }
                        ]
                    },
                    decisionC: {
                        labelKey: 'r3_c_label',
                        options: [
                            { value: 0, labelKey: 'r3_c_opt0', cost: 0 },
                            { value: 1, labelKey: 'r3_c_opt1', cost: 200000 },
                            { value: 2, labelKey: 'r3_c_opt2', cost: 100000 }
                        ]
                    }
                },
                {
                    icon: '\u{1F465}',
                    titleKey: 'r4_title',
                    descKey: 'r4_desc',
                    decisionA: {
                        labelKey: 'r4_a_label',
                        options: [
                            { value: 0, labelKey: 'r4_a_opt0', cost: 0 },
                            { value: 1, labelKey: 'r4_a_opt1', cost: 600000 },
                            { value: 2, labelKey: 'r4_a_opt2', cost: 1800000 },
