        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var iconEl = document.getElementById('roundIcon');
            if (iconEl) iconEl.textContent = round.icon;

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.descKey);

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';

            var self = this;
            ['A', 'B', 'C'].forEach(function(letter) {
                var key = 'decision' + letter;
                var decDef = round[key];
                var sel = document.getElementById(key);
                var lbl = document.getElementById('label' + letter);
                var costHint = document.getElementById('cost' + letter);

                if (lbl) lbl.textContent = t(decDef.labelKey);
                if (sel) {
                    sel.innerHTML = '';
                    decDef.options.forEach(function(opt) {
                        var o = document.createElement('option');
                        o.value = opt.value;
                        var costStr = opt.cost > 0 ? ' ($' + (opt.cost / 1000000).toFixed(1) + 'M)' : ' (Free)';
                        o.textContent = t(opt.labelKey) + costStr;
                        sel.appendChild(o);
                    });
                    sel.onchange = function() {
                        var chosen = decDef.options[parseInt(sel.value)];
                        if (costHint && chosen) {
                            costHint.textContent = chosen.cost > 0 ? t('cost_label') + ': $' + (chosen.cost / 1000000).toFixed(1) + 'M' : '';
                        }
                    };
                }
                if (costHint) costHint.textContent = '';
            });
        }

